{
  "implementation": "def solve(case):
    nodes = case.get('nodes', [])
    required_symbols = case.get('required_symbols', [])
    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError('nodes must be a non-empty list')
    node_map = {}
    children_map = {}
    for n in nodes:
        nid = n['id']
        parent = n.get('parent')
        node_map[nid] = n
        if parent is not None:
            children_map.setdefault(parent, []).append(nid)
    roots = [nid for nid, n in node_map.items() if n.get('parent') is None]
    if len(roots) != 1:
        raise ValueError('Must have exactly one root')
    root_id = roots[0]
    candidate_order = sorted(node_map.keys(), key=lambda nid: (-node_map[nid]['depth'], nid))
    retained = set(node_map.keys())
    removed = []
    symbol_counts = {}
    for n in node_map.values():
        sym = n['symbol']
        symbol_counts[sym] = symbol_counts.get(sym, 0) + 1
    for nid in candidate_order:
        if nid not in retained:
            continue
        node = node_map[nid]
        if nid == root_id:
            continue
        if not node.get('removable', False):
            continue
        children = children_map.get(nid, [])
        if any(c in retained for c in children):
            continue
        sym = node['symbol']
        if sym in required_symbols:
            if symbol_counts.get(sym, 0) <= 1:
                continue
        retained.remove(nid)
        removed.append(nid)
        symbol_counts[sym] -= 1
    retained_list = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_list}"
}
